/** Small numeric helpers shared by the engine modules. */

export const sigmoid = (x: number): number => 1 / (1 + Math.exp(-x));

export const logit = (p: number): number => Math.log(p / (1 - p));

export const clamp = (x: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, x));

/** Tolerance for comparing averages of fractional scores (e.g. 0.6 + 0.6 + …) against thresholds. */
export const EPSILON = 1e-9;

/** Elo-lite mastery model (design-plan §7.3, principle P5). */
import type { ConceptMastery, Familiarity } from "@/lib/contracts/engine";
import type { Verdict } from "@/lib/contracts/moment";
import { clamp, sigmoid } from "./math";

/** Starting θ by self-reported familiarity (design-plan §7.3). */
export const INITIAL_THETA: Record<Familiarity, number> = { new: 1.5, some: 2.5, comfortable: 3.5 };

/** Slope of the logistic: P(correct) = σ(SLOPE·(θ − b)) (design-plan §7.3). */
export const SLOPE = 1.2;

/** Learning rate: fast while we know little about the learner, then slower (design-plan §7.3). */
export const K_EARLY = 0.6;
export const K_LATE = 0.3;
export const K_EARLY_ATTEMPTS = 3; // K_EARLY applies while n < this

/** θ bounds: one step beyond the 1–5 difficulty scale on each side. */
export const THETA_MIN = 0;
export const THETA_MAX = 6;

/** Mastered = enough attempts and P(correct at a medium question) ≥ threshold (design-plan §7.3). */
export const MASTERY_MIN_ATTEMPTS = 2;
export const MASTERY_REFERENCE_DIFFICULTY = 3;
export const MASTERY_P_THRESHOLD = 0.8;

/** A mastered concept unseen for longer than this resurfaces as review (design-plan §7.3). */
export const REVIEW_AFTER_MS = 24 * 60 * 60 * 1000;

/** Outcome scores (design-plan §7.3). Skipped answers have no score and never update mastery. */
export const SCORE = { correct: 1, correctAfterMC: 0.6, partial: 0.5, incorrect: 0 } as const;

export function scoreFor(verdict: Verdict, afterMC: boolean): number {
  if (verdict === "correct") return afterMC ? SCORE.correctAfterMC : SCORE.correct;
  return verdict === "partial" ? SCORE.partial : SCORE.incorrect;
}

export function thetaOf(m: ConceptMastery | undefined, familiarity: Familiarity): number {
  return m ? m.theta : INITIAL_THETA[familiarity];
}

export function pCorrect(theta: number, difficulty: number): number {
  return sigmoid(SLOPE * (theta - difficulty));
}

export function updateMastery(
  prev: ConceptMastery | undefined,
  score: number,
  difficulty: number,
  familiarity: Familiarity,
  now: number,
): ConceptMastery {
  const theta = thetaOf(prev, familiarity);
  const n = prev?.n ?? 0;
  const k = n < K_EARLY_ATTEMPTS ? K_EARLY : K_LATE;
  const next = theta + k * (score - pCorrect(theta, difficulty));
  return { theta: clamp(next, THETA_MIN, THETA_MAX), n: n + 1, lastSeen: now };
}

export function isMastered(m: ConceptMastery | undefined): boolean {
  return (
    !!m &&
    m.n >= MASTERY_MIN_ATTEMPTS &&
    pCorrect(m.theta, MASTERY_REFERENCE_DIFFICULTY) >= MASTERY_P_THRESHOLD
  );
}

export function reviewDue(m: ConceptMastery | undefined, now: number): boolean {
  return !!m && isMastered(m) && now - m.lastSeen > REVIEW_AFTER_MS;
}

/** Target difficulty: aim each question at a success-rate band (design-plan §7.3, research/01-challenge-ratio.md). */
import type { ConceptMastery, DifficultyKind, Familiarity, Outcome } from "@/lib/contracts/engine";
import { clamp, EPSILON, logit } from "./math";
import { SLOPE, thetaOf } from "./mastery";

/** Target P(correct) per kind; research suggests 85–90% new, 75–85% practice, 65–80% boss. */
export const TARGET_SUCCESS: Record<DifficultyKind, number> = {
  first_exposure: 0.87,
  practice: 0.8,
  boss: 0.72,
};

/** Rolling adjustment: back off fast, ramp up slowly (research/01, design implication 3). */
export const ROLLING_WINDOW = 5;
export const ROLLING_MIN_OUTCOMES = 3;
export const ROLLING_HIGH_ACCURACY = 0.9;
export const ROLLING_LOW_ACCURACY = 0.6;
export const RAMP_UP_STEP = 0.5;
export const BACK_OFF_STEP = -1;

export const DIFFICULTY_MIN = 1;
export const DIFFICULTY_MAX = 5;

/** Mean score over the last ROLLING_WINDOW outcomes, or null with fewer than ROLLING_MIN_OUTCOMES. */
export function rollingAccuracy(recent: Outcome[]): number | null {
  const window = recent.slice(-ROLLING_WINDOW);
  if (window.length < ROLLING_MIN_OUTCOMES) return null;
  return window.reduce((sum, o) => sum + o.score, 0) / window.length;
}

export function rollingAdjustment(recent: Outcome[]): number {
  const acc = rollingAccuracy(recent);
  if (acc === null) return 0;
  if (acc >= ROLLING_HIGH_ACCURACY - EPSILON) return RAMP_UP_STEP;
  if (acc <= ROLLING_LOW_ACCURACY + EPSILON) return BACK_OFF_STEP;
  return 0;
}

/** Solves σ(SLOPE·(θ − b)) = target for b, adjusts for recent accuracy, then rounds and clamps to 1–5. */
export function targetDifficulty(
  m: ConceptMastery | undefined,
  kind: DifficultyKind,
  familiarity: Familiarity,
  recent: Outcome[],
): number {
  const b = thetaOf(m, familiarity) - logit(TARGET_SUCCESS[kind]) / SLOPE + rollingAdjustment(recent);
  return clamp(Math.round(b), DIFFICULTY_MIN, DIFFICULTY_MAX);
}

/** Value thresholds and optional guardrail caps (design-plan §7.2, product-vision "Pacing engine"). */
import type { EngineState, GuardrailMode, UserSettings } from "@/lib/contracts/engine";

/** Minimum learning_value with guardrails off (the default). */
export const DEFAULT_VALUE_THRESHOLD = 4;

export const VALUE_THRESHOLD: Record<GuardrailMode, number> = {
  light: 4,
  balanced: 4,
  strict: 5, // "only the highest-value moments"
};

/** Rolling window for per-time caps (design-plan §7.2: "per 10 min"). */
export const CAP_WINDOW_MS = 10 * 60 * 1000;

export interface Caps {
  maxPerWindow?: number; // moments shown within CAP_WINDOW_MS
  minTurnsBetween?: number; // work turns since the last shown moment
}

export const CAPS: Record<GuardrailMode, Caps> = {
  light: { minTurnsBetween: 1 },
  balanced: { maxPerWindow: 4, minTurnsBetween: 2 },
  strict: { maxPerWindow: 2 },
};

export function valueThreshold(settings: UserSettings): number {
  return settings.guardrails.enabled ? VALUE_THRESHOLD[settings.guardrails.mode] : DEFAULT_VALUE_THRESHOLD;
}

/** Moments shown in the half-open window (now − CAP_WINDOW_MS, now]. */
export function momentsInWindow(state: EngineState, now: number): number {
  return state.momentsShownAt.filter((t) => t <= now && now - t < CAP_WINDOW_MS).length;
}

/** True if showing another moment now would break the mode's caps. Turn spacing only applies after a first moment. */
export function capsExceeded(state: EngineState, mode: GuardrailMode, now: number): boolean {
  const { maxPerWindow, minTurnsBetween } = CAPS[mode];
  if (maxPerWindow !== undefined && momentsInWindow(state, now) >= maxPerWindow) return true;
  const shownBefore = state.momentsShownAt.length > 0;
  return minTurnsBetween !== undefined && shownBefore && state.turnsSinceMoment < minTurnsBetween;
}

/** The gate: code decides whether Claude's candidate moment is shown (design-plan §7.1, principle P8). */
import type { DifficultyKind, GateContext, GateDecision } from "@/lib/contracts/engine";
import type { LearningMomentInput } from "@/lib/contracts/moment";
import { targetDifficulty } from "./difficulty";
import { capsExceeded, valueThreshold } from "./guardrails";
import { isMastered, reviewDue } from "./mastery";

/** Candidates this far (or further) from the target difficulty are off the challenge band (design-plan §7.1). */
export const OFF_BAND_DISTANCE = 2;

/** A top-value moment that prevents a costly mistake may bypass the value threshold and caps. */
export function isBreakthrough(c: LearningMomentInput): boolean {
  return c.costly_mistake && c.learning_value === 5;
}

export function gate(candidate: LearningMomentInput, ctx: GateContext): GateDecision {
  const { state, mastery, settings, familiarity, now } = ctx;
  const breakthrough = isBreakthrough(candidate);
  const m = mastery[candidate.concept];

  if (state.pendingMomentId !== undefined) return { action: "skip", reason: "one_at_a_time" };

  if (candidate.learning_value < valueThreshold(settings) && !breakthrough) {
    return { action: "skip", reason: "low_value" };
  }

  if (isMastered(m) && !reviewDue(m, now)) return { action: "skip", reason: "mastered" };

  const kind: DifficultyKind = candidate.first_exposure || !m ? "first_exposure" : "practice";
  const target = targetDifficulty(m, kind, familiarity, state.recentOutcomes);
  if (Math.abs(candidate.difficulty - target) >= OFF_BAND_DISTANCE) return { action: "skip", reason: "off_band" };

  const { enabled, mode } = settings.guardrails;
  if (enabled && !breakthrough && capsExceeded(state, mode, now)) {
    return mode === "strict" ? { action: "defer", reason: "cap" } : { action: "skip", reason: "cap" };
  }

  return { action: "show" };
}

/** Boss timing and outcome (design-plan §7.4). */
import type { BossOutcome, EngineState } from "@/lib/contracts/engine";

/** Distinct concepts practised since the last boss before another is due. */
export const BOSS_MIN_CONCEPTS = 3;
/** Minimum gap between boss starts. */
export const BOSS_COOLDOWN_MS = 3 * 60 * 1000;
/** Don't start a boss in the final minute of the session clock (it would run past the end). */
export const BOSS_MIN_REMAINING_MS = 60 * 1000;

export function bossDue(state: EngineState, now: number, sessionEndsAt: number): boolean {
  if (new Set(state.conceptsSinceBoss).size < BOSS_MIN_CONCEPTS) return false;
  if (state.bosses.some((b) => now - b.startedAt < BOSS_COOLDOWN_MS)) return false;
  // Past the end the user chose "Keep going" (P7), so bosses are allowed again.
  const inFinalMinute = now >= sessionEndsAt - BOSS_MIN_REMAINING_MS && now < sessionEndsAt;
  return !inFinalMinute;
}

/** hits may be fractional (a partial answer is half a hit). */
export function bossOutcome(hits: number, maxHits: number): BossOutcome {
  if (hits >= maxHits) return "flawless";
  if (hits * 2 >= maxHits) return "victory";
  return "retreat";
}

/** Immutable EngineState transitions. Every helper returns a new object and never mutates its input. */
import type { BossOutcome, BossRecord, EngineState, Outcome } from "@/lib/contracts/engine";

/** recentOutcomes keeps the latest N (plenty for the rolling window and summaries). */
export const RECENT_OUTCOMES_CAP = 20;

export function recordShown(state: EngineState, momentId: string, now: number): EngineState {
  return { ...state, pendingMomentId: momentId, momentsShownAt: [...state.momentsShownAt, now], turnsSinceMoment: 0 };
}

export function recordOutcome(state: EngineState, outcome: Outcome): EngineState {
  return {
    ...state,
    pendingMomentId: state.pendingMomentId === outcome.momentId ? undefined : state.pendingMomentId,
    recentOutcomes: [...state.recentOutcomes, outcome].slice(-RECENT_OUTCOMES_CAP),
    conceptsSinceBoss: state.conceptsSinceBoss.includes(outcome.concept)
      ? [...state.conceptsSinceBoss]
      : [...state.conceptsSinceBoss, outcome.concept],
  };
}

/** Clears the pending moment without an outcome (learner skipped or deferred it; mastery is not updated). */
export function recordSkipped(state: EngineState, momentId: string): EngineState {
  return { ...state, pendingMomentId: state.pendingMomentId === momentId ? undefined : state.pendingMomentId };
}

export function recordWorkTurn(state: EngineState): EngineState {
  return { ...state, turnsSinceMoment: state.turnsSinceMoment + 1 };
}

export function recordBossStarted(state: EngineState, boss: BossRecord): EngineState {
  return { ...state, bosses: [...state.bosses, { ...boss, concepts: [...boss.concepts] }] };
}

/** Sets the boss outcome and starts a fresh concept count toward the next boss. */
export function recordBossFinished(state: EngineState, bossId: string, outcome: BossOutcome): EngineState {
  return {
    ...state,
    bosses: state.bosses.map((b) => (b.id === bossId ? { ...b, outcome } : b)),
    conceptsSinceBoss: [],
  };
}

/** XP per event (design-plan §12). XP is only ever added, never subtracted. */
import type { BossOutcome, XpEvent } from "@/lib/contracts/engine";
import type { Verdict } from "@/lib/contracts/moment";

export const XP = {
  answer: { correct: 10, correctAfterMC: 5, partial: 5, incorrect: 0 },
  prediction: { correct: 10, partial: 5, incorrect: 0 } satisfies Record<Verdict, number>,
  bossHit: { full: 15, partial: 8 },
  // A retreat still pays: never punish.
  bossOutcome: { flawless: 75, victory: 50, retreat: 20 } satisfies Record<BossOutcome, number>,
  sessionComplete: 30,
} as const;

export function xpFor(event: XpEvent): number {
  switch (event.kind) {
    case "answer":
      if (event.verdict === "correct") return event.afterMC ? XP.answer.correctAfterMC : XP.answer.correct;
      return XP.answer[event.verdict];
    case "prediction":
      return XP.prediction[event.verdict];
    case "boss_hit":
      return event.partial ? XP.bossHit.partial : XP.bossHit.full;
    case "boss_outcome":
      return XP.bossOutcome[event.outcome];
    case "session_complete":
      return XP.sessionComplete;
  }
}

/** Permanent player levels and their unlocks (design-plan §12). */
import type { LevelInfo, LevelReward } from "@/lib/contracts/engine";

/** XP from L1 to L2; each later step needs LEVEL_STEP_GROWTH more than the previous one. */
export const FIRST_LEVEL_STEP = 100;
export const LEVEL_STEP_GROWTH = 50; // cumulative thresholds 100 / 250 / 450 / 700 / 1,000 / …

export const LEVEL_REWARDS: readonly LevelReward[] = [
  { level: 2, kind: "theme", id: "sunset", label: "Sunset theme" },
  { level: 3, kind: "sound_pack", id: "marimba", label: "Marimba sound pack" },
  { level: 4, kind: "theme", id: "forest", label: "Forest theme" },
  { level: 5, kind: "theme", id: "night", label: "Night Sky theme" },
  { level: 6, kind: "sound_pack", id: "retro", label: "Retro sound pack" },
  { level: 7, kind: "theme", id: "sakura", label: "Sakura theme" },
  { level: 8, kind: "theme", id: "parchment", label: "Parchment theme" },
  { level: 9, kind: "sound_pack", id: "nature", label: "Nature sound pack" },
  { level: 10, kind: "theme", id: "matcha", label: "Matcha theme" },
];

export function levelFor(totalXp: number): LevelInfo {
  const xp = Math.max(0, totalXp);
  let level = 1;
  let start = 0;
  let step = FIRST_LEVEL_STEP;
  while (xp >= start + step) {
    start += step;
    step += LEVEL_STEP_GROWTH;
    level++;
  }
  return { level, xp: totalXp, levelStartXp: start, nextLevelXp: start + step };
}

/** Rewards unlocked by levelling from `fromLevel` to `toLevel`, i.e. levels in (fromLevel, toLevel]. */
export function rewardsBetween(fromLevel: number, toLevel: number): LevelReward[] {
  return LEVEL_REWARDS.filter((r) => r.level > fromLevel && r.level <= toLevel).map((r) => ({ ...r }));
}

/** Engine summary for the work model's dynamic context (design-plan §7.3, §9.1). */
import type { EngineSummary, GateContext } from "@/lib/contracts/engine";
import { rollingAccuracy, targetDifficulty } from "./difficulty";
import { valueThreshold } from "./guardrails";
import { isMastered, reviewDue } from "./mastery";

export const SUMMARY_RECENT_OUTCOMES = 3;

export function summarize(ctx: GateContext): EngineSummary {
  const { state, mastery, settings, familiarity, now } = ctx;
  const recent = state.recentOutcomes;
  return {
    guardrails: { ...settings.guardrails },
    valueThreshold: valueThreshold(settings),
    targetDifficulty: {
      firstExposure: targetDifficulty(undefined, "first_exposure", familiarity, recent),
      practice: targetDifficulty(undefined, "practice", familiarity, recent),
    },
    // Matches the gate: review-due concepts are left out so Claude may quiz them again.
    masteredConcepts: Object.keys(mastery)
      .filter((c) => isMastered(mastery[c]) && !reviewDue(mastery[c], now))
      .sort(),
    conceptsSinceBoss: [...state.conceptsSinceBoss],
    rollingAccuracy: rollingAccuracy(recent),
    recentOutcomes: recent
      .slice(-SUMMARY_RECENT_OUTCOMES)
      .map((o) => ({ concept: o.concept, type: o.type, score: o.score })),
  };
}

/**
 * Pacing engine (design-plan §7, §12): pure, deterministic, and unit-tested.
 * Code paces, Claude creates (P8): Claude proposes moments; this module decides what is shown and how hard.
 */
import type { EngineApi } from "@/lib/contracts/engine";
import { bossDue, bossOutcome } from "./boss";
import { targetDifficulty } from "./difficulty";
import { gate } from "./gate";
import { levelFor, rewardsBetween } from "./levels";
import { isMastered, reviewDue, updateMastery } from "./mastery";
import { recordOutcome, recordShown, recordWorkTurn } from "./state";
import { summarize } from "./summary";
import { xpFor } from "./xp";

export const engine: EngineApi = {
  gate,
  updateMastery,
  targetDifficulty,
  isMastered,
  reviewDue,
  bossDue,
  bossOutcome,
  summarize,
  recordShown,
  recordOutcome,
  recordWorkTurn,
  xpFor,
  levelFor,
  rewardsBetween,
};

export { bossDue, bossOutcome } from "./boss";
export { rollingAccuracy, targetDifficulty, TARGET_SUCCESS } from "./difficulty";
export { gate, isBreakthrough } from "./gate";
export { CAPS, capsExceeded, valueThreshold } from "./guardrails";
export { LEVEL_REWARDS, levelFor, rewardsBetween } from "./levels";
export { isMastered, reviewDue, SCORE, scoreFor, updateMastery } from "./mastery";
export {
  recordBossFinished,
  recordBossStarted,
  recordOutcome,
  recordShown,
  recordSkipped,
  recordWorkTurn,
} from "./state";
export { summarize } from "./summary";
export { XP, xpFor } from "./xp";

