import { describe, expect, it } from "vitest";
import {
  INITIAL_THETA,
  isMastered,
  pCorrect,
  reviewDue,
  REVIEW_AFTER_MS,
  SCORE,
  scoreFor,
  updateMastery,
} from "./mastery";
import { logit } from "./math";
import { DAY, T0 } from "./test-helpers";

// θ at which P(correct at b=3) is exactly 0.8.
const MASTERY_THETA = 3 + logit(0.8) / 1.2;

describe("pCorrect", () => {
