    let s = frozen(initialEngineState());
    s = recordOutcome(s, outcome(1, 0, "a"));
    s = recordOutcome(s, outcome(0, 1, "b"));
    s = recordOutcome(s, outcome(1, 2, "a"));
    expect(s.conceptsSinceBoss).toEqual(["a", "b"]);
