        "updateMastery",
        "xpFor",
      ].sort(),
    );
  });

  it("runs a short session end to end", () => {
    const familiarity = "some" as const;
    let state = initialEngineState();
    let mastery = {} as Record<string, ReturnType<typeof engine.updateMastery>>;
    let now = T0;
    let xp = 0;

