/** Fixtures shared by the engine tests (not imported by production code). */
import {
  initialEngineState,
  type EngineState,
  type GateContext,
  type GuardrailMode,
  type Outcome,
  type UserSettings,
} from "@/lib/contracts/engine";
import type { LearningMomentInput } from "@/lib/contracts/moment";

export const MIN = 60 * 1000;
export const DAY = 24 * 60 * MIN;
export const T0 = 1_760_000_000_000;

export function candidate(overrides: Partial<LearningMomentInput> = {}): LearningMomentInput {
  return {
    type: "decide",
    concept: "train_test_split",
    question: "Why hold out a test set?",
    ideal_answer: "To estimate generalisation on unseen data.",
    rubric: { key_points: ["unseen data"] },
    mc_fallback: { options: ["a", "b", "c"], correct_index: 0, why: ["x", "y", "z"] },
    difficulty: 1,
    first_exposure: true,
    learning_value: 4,
    value_reason: "core idea",
    costly_mistake: false,
    timing: "before_step",
    ...overrides,
  };
}

export function settings(guardrails?: { enabled: boolean; mode: GuardrailMode }): UserSettings {
  return {
    sound: true,
    volume: 0.4,
    theme: "frost",
    soundPack: "default",
    guardrails: guardrails ?? { enabled: false, mode: "balanced" },
  };
}

export function ctx(overrides: Partial<GateContext> = {}): GateContext {
  return {
    state: initialEngineState(),
    mastery: {},
    settings: settings(),
    familiarity: "some",
    now: T0,
    ...overrides,
  };
}

export function outcome(score: number, i = 0, concept = "c"): Outcome {
  return { momentId: `m${i}`, concept, type: "decide", score, at: T0 + i };
}

export function outcomes(scores: number[]): Outcome[] {
  return scores.map((s, i) => outcome(s, i));
}

export function stateWith(overrides: Partial<EngineState>): EngineState {
  return { ...initialEngineState(), ...overrides };
}

/** Deterministic PRNG (mulberry32) for simulation tests. */
export function seededRng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import { describe, expect, it } from "vitest";
import {
  INITIAL_THETA,
  isMastered,
  pCorrect,
  reviewDue,
  REVIEW_AFTER_MS,
  SCORE,
  scoreFor,
  updateMastery,
} from "./mastery";
import { logit } from "./math";
import { DAY, T0 } from "./test-helpers";

// θ at which P(correct at b=3) is exactly 0.8.
const MASTERY_THETA = 3 + logit(0.8) / 1.2;

describe("pCorrect", () => {
  it("is 0.5 when θ equals difficulty and follows σ(1.2·(θ − b))", () => {
    expect(pCorrect(3, 3)).toBeCloseTo(0.5);
    expect(pCorrect(4, 3)).toBeCloseTo(1 / (1 + Math.exp(-1.2)));
    expect(pCorrect(2, 3)).toBeCloseTo(1 / (1 + Math.exp(1.2)));
  });
});

describe("scoreFor", () => {
  it("maps verdicts to scores", () => {
    expect(scoreFor("correct", false)).toBe(1);
    expect(scoreFor("correct", true)).toBe(0.6);
    expect(scoreFor("partial", false)).toBe(0.5);
    expect(scoreFor("partial", true)).toBe(0.5);
    expect(scoreFor("incorrect", false)).toBe(0);
    expect(SCORE).toEqual({ correct: 1, correctAfterMC: 0.6, partial: 0.5, incorrect: 0 });
  });
});

describe("updateMastery", () => {
  it("starts θ from familiarity", () => {
    expect(INITIAL_THETA).toEqual({ new: 1.5, some: 2.5, comfortable: 3.5 });
    for (const fam of ["new", "some", "comfortable"] as const) {
      const b = INITIAL_THETA[fam];
      // At b = θ, p = 0.5, so a correct answer moves θ by K·0.5 = 0.3.
      expect(updateMastery(undefined, 1, b, fam, T0).theta).toBeCloseTo(INITIAL_THETA[fam] + 0.3);
    }
  });

  it("applies θ += K·(score − p) with K = 0.6 for n < 3", () => {
    const m = updateMastery(undefined, 1, 2, "some", T0);
    const p = pCorrect(2.5, 2);
    expect(m.theta).toBeCloseTo(2.5 + 0.6 * (1 - p));
    expect(m).toMatchObject({ n: 1, lastSeen: T0 });
  });

  it("uses K = 0.6 at n = 2 and K = 0.3 from n = 3", () => {
    const atTwo = updateMastery({ theta: 3, n: 2, lastSeen: 0 }, 0, 3, "new", T0);
    expect(atTwo.theta).toBeCloseTo(3 - 0.6 * 0.5);
    expect(atTwo.n).toBe(3);
    const atThree = updateMastery({ theta: 3, n: 3, lastSeen: 0 }, 0, 3, "new", T0);
    expect(atThree.theta).toBeCloseTo(3 - 0.3 * 0.5);
    expect(atThree.n).toBe(4);
  });

  it("ignores familiarity once a record exists", () => {
    const prev = { theta: 2, n: 1, lastSeen: 0 };
    expect(updateMastery(prev, 0.5, 2, "comfortable", T0)).toEqual(updateMastery(prev, 0.5, 2, "new", T0));
  });

  it("handles partial and after-MC scores", () => {
    const prev = { theta: 3, n: 5, lastSeen: 0 };
    expect(updateMastery(prev, 0.5, 3, "some", T0).theta).toBeCloseTo(3); // score equals p
    expect(updateMastery(prev, 0.6, 3, "some", T0).theta).toBeCloseTo(3 + 0.3 * 0.1);
  });

  it("clamps θ to [0, 6]", () => {
    expect(updateMastery({ theta: 5.9, n: 0, lastSeen: 0 }, 1, 5, "some", T0).theta).toBe(6);
    expect(updateMastery({ theta: 0.1, n: 0, lastSeen: 0 }, 0, 1, "some", T0).theta).toBe(0);
  });

  it("does not mutate the previous record", () => {
    const prev = Object.freeze({ theta: 2, n: 1, lastSeen: 0 });
    const next = updateMastery(prev, 1, 2, "some", T0);
    expect(next).not.toBe(prev);
    expect(prev).toEqual({ theta: 2, n: 1, lastSeen: 0 });
  });
});

describe("isMastered", () => {
  it("is false without a record", () => {
    expect(isMastered(undefined)).toBe(false);
  });

  it("requires n ≥ 2", () => {
    expect(isMastered({ theta: 6, n: 1, lastSeen: 0 })).toBe(false);
    expect(isMastered({ theta: 6, n: 2, lastSeen: 0 })).toBe(true);
  });

  it("requires P(correct at b=3) ≥ 0.8 (θ ≈ 4.155)", () => {
    expect(isMastered({ theta: MASTERY_THETA + 1e-6, n: 2, lastSeen: 0 })).toBe(true);
    expect(isMastered({ theta: MASTERY_THETA - 1e-6, n: 2, lastSeen: 0 })).toBe(false);
  });
});

describe("reviewDue", () => {
  const mastered = { theta: 5, n: 3, lastSeen: T0 };

  it("is false for missing or unmastered concepts", () => {
    expect(reviewDue(undefined, T0 + 10 * DAY)).toBe(false);
    expect(reviewDue({ theta: 2, n: 3, lastSeen: T0 }, T0 + 10 * DAY)).toBe(false);
  });

  it("becomes true strictly after one day unseen", () => {
    expect(REVIEW_AFTER_MS).toBe(DAY);
    expect(reviewDue(mastered, T0 + DAY)).toBe(false);
    expect(reviewDue(mastered, T0 + DAY + 1)).toBe(true);
  });
});

import { describe, expect, it } from "vitest";
import type { Familiarity } from "@/lib/contracts/engine";
import { rollingAccuracy, rollingAdjustment, targetDifficulty, TARGET_SUCCESS } from "./difficulty";
import { updateMastery, pCorrect } from "./mastery";
import { logit } from "./math";
import { outcome, outcomes, seededRng, T0 } from "./test-helpers";

const m = (theta: number) => ({ theta, n: 3, lastSeen: 0 });
const raw = (theta: number, target: number) => theta - logit(target) / 1.2;

describe("rollingAccuracy", () => {
  it("is null with fewer than 3 outcomes", () => {
    expect(rollingAccuracy([])).toBeNull();
    expect(rollingAccuracy(outcomes([1, 1]))).toBeNull();
  });

  it("averages scores over the last 5 only", () => {
    expect(rollingAccuracy(outcomes([1, 0, 1]))).toBeCloseTo(2 / 3);
    expect(rollingAccuracy(outcomes([0, 0, 0, 1, 1, 1, 1, 1]))).toBe(1);
    expect(rollingAccuracy(outcomes([1, 0.6, 0.5, 0, 1]))).toBeCloseTo(3.1 / 5);
  });
});

describe("rollingAdjustment", () => {
  it("is 0 with fewer than 3 outcomes", () => {
    expect(rollingAdjustment(outcomes([0, 0]))).toBe(0);
    expect(rollingAdjustment(outcomes([1, 1]))).toBe(0);
  });

  it("ramps up +0.5 at ≥ 90% (boundary inclusive)", () => {
    expect(rollingAdjustment(outcomes([1, 1, 1, 1, 0.5]))).toBe(0.5); // exactly 0.9
    expect(rollingAdjustment(outcomes([1, 1, 1]))).toBe(0.5);
    expect(rollingAdjustment(outcomes([1, 1, 1, 1, 0.4]))).toBe(0); // 0.88
  });

  it("backs off −1 at ≤ 60% (boundary inclusive, robust to float sums)", () => {
    expect(rollingAdjustment(outcomes([1, 1, 1, 0, 0]))).toBe(-1); // exactly 0.6
    expect(rollingAdjustment(outcomes([0.6, 0.6, 0.6, 0.6, 0.6]))).toBe(-1);
    expect(rollingAdjustment(outcomes([1, 1, 1, 0.5, 0]))).toBe(0); // 0.7
  });
});

describe("targetDifficulty", () => {
  it("uses the documented target success rates", () => {
    expect(TARGET_SUCCESS).toEqual({ first_exposure: 0.87, practice: 0.8, boss: 0.72 });
  });

  it("solves b = θ − logit(target)/1.2 and rounds", () => {
    // θ = 4: first exposure 2.42 → 2, practice 2.84 → 3, boss 3.21 → 3
    expect(targetDifficulty(m(4), "first_exposure", "some", [])).toBe(Math.round(raw(4, 0.87)));
    expect(targetDifficulty(m(4), "first_exposure", "some", [])).toBe(2);
    expect(targetDifficulty(m(4), "practice", "some", [])).toBe(3);
    expect(targetDifficulty(m(4), "boss", "some", [])).toBe(3);
    // θ = 5: 3.42 → 3, 3.84 → 4, 4.21 → 4
    expect(targetDifficulty(m(5), "first_exposure", "some", [])).toBe(3);
    expect(targetDifficulty(m(5), "practice", "some", [])).toBe(4);
    expect(targetDifficulty(m(5), "boss", "some", [])).toBe(4);
  });

  it("falls back to familiarity θ with no record", () => {
    const cases: [Familiarity, number, number][] = [
      ["new", 1, 1], // raw −0.08 / 0.35 → clamp 1
      ["some", 1, 1], // raw 0.92 / 1.35
      ["comfortable", 2, 2], // raw 1.92 / 2.35
    ];
    for (const [fam, first, practice] of cases) {
      expect(targetDifficulty(undefined, "first_exposure", fam, [])).toBe(first);
      expect(targetDifficulty(undefined, "practice", fam, [])).toBe(practice);
    }
  });

  it("applies the rolling adjustment before rounding", () => {
    // θ = 4, practice: raw 2.845. +0.5 → 3.345 → 3; −1 → 1.845 → 2.
    const hot = outcomes([1, 1, 1, 1, 1]);
    const cold = outcomes([0, 0, 0, 1, 1]);
    expect(targetDifficulty(m(4), "practice", "some", hot)).toBe(3);
    expect(targetDifficulty(m(4), "practice", "some", cold)).toBe(2);
    // θ = 4.3, practice: raw 3.145 → 3; +0.5 → 3.645 → 4.
    expect(targetDifficulty(m(4.3), "practice", "some", [])).toBe(3);
    expect(targetDifficulty(m(4.3), "practice", "some", hot)).toBe(4);
  });

  it("ignores the adjustment with fewer than 3 outcomes", () => {
    expect(targetDifficulty(m(4.3), "practice", "some", outcomes([1, 1]))).toBe(3);
  });

  it("clamps to 1–5", () => {
    expect(targetDifficulty(m(0), "first_exposure", "some", outcomes([0, 0, 0]))).toBe(1);
    expect(targetDifficulty(m(6), "practice", "some", outcomes([1, 1, 1]))).toBe(5);
  });
});

describe("simulated learner", () => {
  /** Runs a learner with fixed true skill through `questions` items on one concept, aimed by targetDifficulty. */
  function simulate(trueTheta: number, familiarity: Familiarity, seed: number, questions = 30): number {
    const rng = seededRng(seed);
    let mastery: ReturnType<typeof updateMastery> | undefined;
    let recent = [] as ReturnType<typeof outcomes>;
    let correct = 0;
    for (let i = 0; i < questions; i++) {
      const kind = mastery ? "practice" : "first_exposure";
      const b = targetDifficulty(mastery, kind, familiarity, recent);
      const score = rng() < pCorrect(trueTheta, b) ? 1 : 0;
      correct += score;
      mastery = updateMastery(mastery, score, b, familiarity, T0 + i);
      recent = [...recent, outcome(score, i)].slice(-20);
    }
    return correct / questions;
  }

  it("lands near the target success band over ~30 questions", () => {
    for (const [trueTheta, fam] of [
      [3, "new"],
      [4, "some"],
      [5, "comfortable"],
    ] as const) {
      const rate = simulate(trueTheta, fam, 42);
      expect(rate).toBeGreaterThanOrEqual(0.7);
      expect(rate).toBeLessThanOrEqual(0.92);
    }
  });

  it("averages close to the practice target across many seeds", () => {
    const rates = Array.from({ length: 40 }, (_, seed) => simulate(4, "some", seed + 1));
    const mean = rates.reduce((a, b) => a + b, 0) / rates.length;
    expect(mean).toBeGreaterThan(0.72);
    expect(mean).toBeLessThan(0.88);
  });
});

import { describe, expect, it } from "vitest";
import { CAP_WINDOW_MS, capsExceeded, momentsInWindow, valueThreshold } from "./guardrails";
import { MIN, settings, stateWith, T0 } from "./test-helpers";

describe("valueThreshold", () => {
  it("is 4 when off, light, or balanced, and 5 for strict", () => {
    expect(valueThreshold(settings())).toBe(4);
    expect(valueThreshold(settings({ enabled: false, mode: "strict" }))).toBe(4);
    expect(valueThreshold(settings({ enabled: true, mode: "light" }))).toBe(4);
    expect(valueThreshold(settings({ enabled: true, mode: "balanced" }))).toBe(4);
    expect(valueThreshold(settings({ enabled: true, mode: "strict" }))).toBe(5);
  });
});

describe("momentsInWindow", () => {
  it("counts moments in the half-open window (now − 10 min, now]", () => {
    expect(CAP_WINDOW_MS).toBe(10 * MIN);
    const state = stateWith({ momentsShownAt: [T0 - 10 * MIN, T0 - 10 * MIN + 1, T0, T0 + 1] });
    // T0 − 10min drops out exactly at the edge; T0 + 1 is in the future and ignored.
    expect(momentsInWindow(state, T0)).toBe(2);
  });
});

describe("capsExceeded", () => {
  it("light: needs ≥ 1 work turn since the last moment", () => {
    expect(capsExceeded(stateWith({ momentsShownAt: [T0], turnsSinceMoment: 0 }), "light", T0)).toBe(true);
    expect(capsExceeded(stateWith({ momentsShownAt: [T0], turnsSinceMoment: 1 }), "light", T0)).toBe(false);
  });

  it("light: has no per-window cap", () => {
    const many = Array.from({ length: 10 }, (_, i) => T0 - i * MIN);
    expect(capsExceeded(stateWith({ momentsShownAt: many, turnsSinceMoment: 1 }), "light", T0)).toBe(false);
  });

  it("does not apply turn spacing before the first moment", () => {
    expect(capsExceeded(stateWith({ turnsSinceMoment: 0 }), "light", T0)).toBe(false);
    expect(capsExceeded(stateWith({ turnsSinceMoment: 0 }), "balanced", T0)).toBe(false);
  });

  it("balanced: needs ≥ 2 turns between moments", () => {
    expect(capsExceeded(stateWith({ momentsShownAt: [T0 - MIN], turnsSinceMoment: 1 }), "balanced", T0)).toBe(true);
    expect(capsExceeded(stateWith({ momentsShownAt: [T0 - MIN], turnsSinceMoment: 2 }), "balanced", T0)).toBe(false);
  });

  it("balanced: allows ≤ 4 per rolling 10 minutes", () => {
    const three = [T0 - 9 * MIN, T0 - 6 * MIN, T0 - 3 * MIN];
    const four = [T0 - 10 * MIN + 1, ...three];
    expect(capsExceeded(stateWith({ momentsShownAt: three, turnsSinceMoment: 5 }), "balanced", T0)).toBe(false);
    expect(capsExceeded(stateWith({ momentsShownAt: four, turnsSinceMoment: 5 }), "balanced", T0)).toBe(true);
    // One millisecond later the oldest moment leaves the window.
    expect(capsExceeded(stateWith({ momentsShownAt: four, turnsSinceMoment: 5 }), "balanced", T0 + 1)).toBe(false);
  });

  it("strict: allows ≤ 2 per rolling 10 minutes, with no turn spacing", () => {
    const one = [T0 - 5 * MIN];
    const two = [T0 - 10 * MIN, T0 - 5 * MIN, T0 - 1];
    expect(capsExceeded(stateWith({ momentsShownAt: one, turnsSinceMoment: 0 }), "strict", T0)).toBe(false);
    expect(capsExceeded(stateWith({ momentsShownAt: two, turnsSinceMoment: 0 }), "strict", T0)).toBe(true);
    expect(capsExceeded(stateWith({ momentsShownAt: two, turnsSinceMoment: 0 }), "strict", T0 + 5 * MIN)).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { gate, isBreakthrough } from "./gate";
import { candidate, ctx, DAY, MIN, outcomes, settings, stateWith, T0 } from "./test-helpers";

const mastered = { theta: 5, n: 3, lastSeen: T0 };
const breakthrough = { costly_mistake: true, learning_value: 5 };

describe("isBreakthrough", () => {
  it("requires costly_mistake and learning_value 5", () => {
    expect(isBreakthrough(candidate(breakthrough))).toBe(true);
    expect(isBreakthrough(candidate({ costly_mistake: true, learning_value: 4 }))).toBe(false);
    expect(isBreakthrough(candidate({ costly_mistake: false, learning_value: 5 }))).toBe(false);
  });
});

describe("gate", () => {
  it("shows a valuable, on-band candidate by default", () => {
    expect(gate(candidate(), ctx())).toEqual({ action: "show" });
  });

  describe("1. one at a time", () => {
    it("skips while a moment is pending, even for breakthroughs", () => {
      const c = ctx({ state: stateWith({ pendingMomentId: "m1" }) });
      expect(gate(candidate(breakthrough), c)).toEqual({ action: "skip", reason: "one_at_a_time" });
    });
  });

  describe("2. learning value", () => {
    it("skips below 4 when guardrails are off", () => {
      expect(gate(candidate({ learning_value: 3 }), ctx())).toEqual({ action: "skip", reason: "low_value" });
      expect(gate(candidate({ learning_value: 4 }), ctx()).action).toBe("show");
    });

    it("needs 5 in strict mode", () => {
      const strict = ctx({ settings: settings({ enabled: true, mode: "strict" }) });
      expect(gate(candidate({ learning_value: 4 }), strict)).toEqual({ action: "skip", reason: "low_value" });
      expect(gate(candidate({ learning_value: 5 }), strict).action).toBe("show");
    });

    it("uses the off threshold when guardrails are disabled, whatever the mode", () => {
      const off = ctx({ settings: settings({ enabled: false, mode: "strict" }) });
      expect(gate(candidate({ learning_value: 4 }), off).action).toBe("show");
    });
  });

  describe("3. mastered", () => {
    it("skips mastered concepts that are not review-due", () => {
      const c = ctx({ mastery: { train_test_split: mastered } });
      expect(gate(candidate({ difficulty: 4, first_exposure: false }), c)).toEqual({ action: "skip", reason: "mastered" });
    });

    it("allows review-due mastered concepts", () => {
      const c = ctx({ mastery: { train_test_split: mastered }, now: T0 + DAY + 1 });
      // θ = 5, practice target = 4
      expect(gate(candidate({ difficulty: 4, first_exposure: false }), c)).toEqual({ action: "show" });
    });

    it("applies even to breakthroughs (they only bypass value and caps)", () => {
      const c = ctx({ mastery: { train_test_split: mastered } });
      expect(gate(candidate({ ...breakthrough, difficulty: 4 }), c).action).toBe("skip");
    });
  });

  describe("4. off band", () => {
    it("skips when |difficulty − target| ≥ 2", () => {
      // familiarity "some", no record → first_exposure target 1
      expect(gate(candidate({ difficulty: 2 }), ctx()).action).toBe("show");
      expect(gate(candidate({ difficulty: 3 }), ctx())).toEqual({ action: "skip", reason: "off_band" });
    });

    it("uses practice targeting for a seen concept that isn't a first exposure", () => {
      const c = ctx({ mastery: { train_test_split: { theta: 4, n: 2, lastSeen: T0 } } });
      // θ = 4: practice target 3, first-exposure target 2
      expect(gate(candidate({ difficulty: 4, first_exposure: false }), c).action).toBe("show");
      expect(gate(candidate({ difficulty: 1, first_exposure: false }), c).action).toBe("skip");
      expect(gate(candidate({ difficulty: 4, first_exposure: true }), c)).toEqual({ action: "skip", reason: "off_band" });
      expect(gate(candidate({ difficulty: 1, first_exposure: true }), c).action).toBe("show");
    });

    it("treats a missing record as first exposure even if the flag is false", () => {
      // comfortable: first-exposure target 2, practice target 2 — use θ-dependent case instead
      const c = ctx({ familiarity: "new" });
      expect(gate(candidate({ difficulty: 3, first_exposure: false }), c)).toEqual({ action: "skip", reason: "off_band" });
    });

    it("follows the rolling adjustment", () => {
      const seen = { train_test_split: { theta: 4, n: 3, lastSeen: T0 } };
      const cold = ctx({ mastery: seen, state: stateWith({ recentOutcomes: outcomes([0, 0, 0]) }) });
      // target drops from 3 to 2, so difficulty 4 is now off band
      expect(gate(candidate({ difficulty: 4, first_exposure: false }), cold)).toEqual({ action: "skip", reason: "off_band" });
    });

    it("applies even to breakthroughs", () => {
      expect(gate(candidate({ ...breakthrough, difficulty: 5 }), ctx()).action).toBe("skip");
    });
  });

  describe("5. guardrail caps", () => {
    const capped = stateWith({ momentsShownAt: [T0 - 4 * MIN, T0 - 2 * MIN], turnsSinceMoment: 0 });

    it("skips with cap in light and balanced", () => {
      for (const mode of ["light", "balanced"] as const) {
        const c = ctx({ state: capped, settings: settings({ enabled: true, mode }) });
        expect(gate(candidate(), c)).toEqual({ action: "skip", reason: "cap" });
      }
    });

    it("defers in strict", () => {
      const c = ctx({ state: capped, settings: settings({ enabled: true, mode: "strict" }) });
      expect(gate(candidate({ learning_value: 5 }), c)).toEqual({ action: "defer", reason: "cap" });
    });

    it("lets a breakthrough through the caps", () => {
      for (const mode of ["light", "balanced", "strict"] as const) {
        const c = ctx({ state: capped, settings: settings({ enabled: true, mode }) });
        expect(gate(candidate(breakthrough), c)).toEqual({ action: "show" });
      }
    });

    it("lets a breakthrough through the value threshold", () => {
      const strict = ctx({ settings: settings({ enabled: true, mode: "strict" }) });
      expect(isBreakthrough(candidate(breakthrough))).toBe(true);
      expect(gate(candidate(breakthrough), strict).action).toBe("show");
    });

    it("ignores caps when guardrails are off", () => {
      const c = ctx({ state: capped, settings: settings({ enabled: false, mode: "strict" }) });
      expect(gate(candidate(), c)).toEqual({ action: "show" });
    });

    it("frees up once the strict window rolls past", () => {
      const c = ctx({ state: capped, settings: settings({ enabled: true, mode: "strict" }), now: T0 + 6 * MIN });
      expect(gate(candidate({ learning_value: 5 }), c)).toEqual({ action: "show" });
    });
  });

  it("checks the branches in order", () => {
    // pending beats low value
    const pendingLow = ctx({ state: stateWith({ pendingMomentId: "x" }) });
    expect(gate(candidate({ learning_value: 1 }), pendingLow)).toMatchObject({ reason: "one_at_a_time" });
    // low value beats mastered
    const masteredCtx = ctx({ mastery: { train_test_split: mastered } });
    expect(gate(candidate({ learning_value: 1 }), masteredCtx)).toMatchObject({ reason: "low_value" });
    // off band beats caps
    const cappedStrict = ctx({
      state: stateWith({ momentsShownAt: [T0, T0] }),
      settings: settings({ enabled: true, mode: "strict" }),
    });
    expect(gate(candidate({ learning_value: 5, difficulty: 5 }), cappedStrict)).toMatchObject({ reason: "off_band" });
  });
});

import { describe, expect, it } from "vitest";
import { bossDue, bossOutcome } from "./boss";
import { MIN, stateWith, T0 } from "./test-helpers";

const ready = stateWith({ conceptsSinceBoss: ["a", "b", "c"] });
const END = T0 + 10 * MIN;

describe("bossDue", () => {
  it("is due with ≥ 3 distinct concepts, no recent boss, and time left", () => {
    expect(bossDue(ready, T0, END)).toBe(true);
  });

  it("needs 3 distinct concepts", () => {
    expect(bossDue(stateWith({ conceptsSinceBoss: ["a", "b"] }), T0, END)).toBe(false);
    expect(bossDue(stateWith({ conceptsSinceBoss: ["a", "b", "b"] }), T0, END)).toBe(false);
    expect(bossDue(stateWith({ conceptsSinceBoss: ["a", "b", "c", "d"] }), T0, END)).toBe(true);
  });

  it("waits 3 minutes after the last boss started", () => {
    const s = { ...ready, bosses: [{ id: "b1", startedAt: T0, concepts: [], outcome: "victory" as const }] };
    expect(bossDue(s, T0 + 3 * MIN - 1, END)).toBe(false);
    expect(bossDue(s, T0 + 3 * MIN, END)).toBe(true);
  });

  it("only considers the most recent boss timing among all bosses", () => {
    const s = {
      ...ready,
      bosses: [
        { id: "b1", startedAt: T0 - 20 * MIN, concepts: [] },
        { id: "b2", startedAt: T0 - MIN, concepts: [] },
      ],
    };
    expect(bossDue(s, T0, END)).toBe(false);
  });

  it("is not due in the final minute", () => {
    expect(bossDue(ready, END - MIN - 1, END)).toBe(true);
    expect(bossDue(ready, END - MIN, END)).toBe(false);
    expect(bossDue(ready, END - 1, END)).toBe(false);
  });

  it("is allowed again once the user keeps going past the end", () => {
    expect(bossDue(ready, END, END)).toBe(true);
    expect(bossDue(ready, END + 5 * MIN, END)).toBe(true);
    expect(bossDue(stateWith({ conceptsSinceBoss: ["a"] }), END + 5 * MIN, END)).toBe(false);
  });
});

describe("bossOutcome", () => {
  it("is flawless with all hits", () => {
    expect(bossOutcome(3, 3)).toBe("flawless");
    expect(bossOutcome(2, 2)).toBe("flawless");
  });

  it("is victory with at least half the hits", () => {
    expect(bossOutcome(2, 3)).toBe("victory");
    expect(bossOutcome(1.5, 3)).toBe("victory"); // exactly half
    expect(bossOutcome(2.5, 3)).toBe("victory");
    expect(bossOutcome(1, 2)).toBe("victory");
  });

  it("is retreat with fewer than half", () => {
    expect(bossOutcome(1, 3)).toBe("retreat");
    expect(bossOutcome(0.5, 2)).toBe("retreat");
    expect(bossOutcome(0, 3)).toBe("retreat");
  });
});

import { describe, expect, it } from "vitest";
import { initialEngineState, type EngineState } from "@/lib/contracts/engine";
import {
  RECENT_OUTCOMES_CAP,
  recordBossFinished,
  recordBossStarted,
  recordOutcome,
  recordShown,
  recordSkipped,
  recordWorkTurn,
} from "./state";
import { outcome, stateWith, T0 } from "./test-helpers";

/** Deep-freezes a state so any in-place mutation throws in strict mode. */
function frozen(state: EngineState): EngineState {
  for (const v of Object.values(state)) if (Array.isArray(v)) Object.freeze(v);
  state.bosses.forEach((b) => Object.freeze(b));
  return Object.freeze(state);
}

describe("recordShown", () => {
  it("sets pending, appends the timestamp, and resets turns", () => {
    const before = frozen(stateWith({ momentsShownAt: [T0 - 1], turnsSinceMoment: 4 }));
    const after = recordShown(before, "m1", T0);
    expect(after).toMatchObject({ pendingMomentId: "m1", momentsShownAt: [T0 - 1, T0], turnsSinceMoment: 0 });
    expect(before).toEqual(stateWith({ momentsShownAt: [T0 - 1], turnsSinceMoment: 4 }));
  });
});

describe("recordOutcome", () => {
  it("clears pending only when the ids match", () => {
    const s = frozen(stateWith({ pendingMomentId: "m0" }));
    expect(recordOutcome(s, outcome(1, 0)).pendingMomentId).toBeUndefined();
    expect(recordOutcome(s, outcome(1, 9)).pendingMomentId).toBe("m0");
  });

  it("appends outcomes, capped at 20 (most recent last)", () => {
    let s = initialEngineState();
    for (let i = 0; i < 25; i++) s = recordOutcome(s, outcome(1, i));
    expect(RECENT_OUTCOMES_CAP).toBe(20);
    expect(s.recentOutcomes).toHaveLength(20);
    expect(s.recentOutcomes[0].momentId).toBe("m5");
    expect(s.recentOutcomes[19].momentId).toBe("m24");
  });

  it("adds the concept to conceptsSinceBoss once", () => {
    let s = frozen(initialEngineState());
    s = recordOutcome(s, outcome(1, 0, "a"));
    s = recordOutcome(s, outcome(0, 1, "b"));
    s = recordOutcome(s, outcome(1, 2, "a"));
    expect(s.conceptsSinceBoss).toEqual(["a", "b"]);
  });

  it("does not mutate its input", () => {
    const before = frozen(stateWith({ conceptsSinceBoss: ["a"], recentOutcomes: [outcome(1, 0, "a")] }));
    const after = recordOutcome(before, outcome(0, 1, "a"));
    expect(after).not.toBe(before);
    expect(after.conceptsSinceBoss).not.toBe(before.conceptsSinceBoss);
    expect(before.recentOutcomes).toHaveLength(1);
  });
});

describe("recordSkipped", () => {
  it("clears a matching pending moment without recording an outcome", () => {
    const s = frozen(stateWith({ pendingMomentId: "m1" }));
    const after = recordSkipped(s, "m1");
    expect(after.pendingMomentId).toBeUndefined();
    expect(after.recentOutcomes).toEqual([]);
    expect(recordSkipped(s, "other").pendingMomentId).toBe("m1");
  });
});

describe("recordWorkTurn", () => {
  it("increments turnsSinceMoment immutably", () => {
    const s = frozen(initialEngineState());
    const after = recordWorkTurn(recordWorkTurn(s));
    expect(after.turnsSinceMoment).toBe(2);
    expect(s.turnsSinceMoment).toBe(0);
  });
});

describe("boss helpers", () => {
  it("recordBossStarted appends a copy of the boss", () => {
    const s = frozen(initialEngineState());
    const boss = { id: "b1", startedAt: T0, concepts: ["a", "b", "c"] };
    const after = recordBossStarted(s, boss);
    expect(after.bosses).toEqual([boss]);
    expect(after.bosses[0]).not.toBe(boss);
    expect(s.bosses).toEqual([]);
  });

  it("recordBossFinished sets the outcome and resets conceptsSinceBoss", () => {
    const s = frozen(
      stateWith({
        conceptsSinceBoss: ["a", "b", "c"],
        bosses: [
          { id: "b0", startedAt: T0 - 1, concepts: [], outcome: "retreat" },
          { id: "b1", startedAt: T0, concepts: ["a"] },
        ],
      }),
    );
    const after = recordBossFinished(s, "b1", "flawless");
    expect(after.bosses.map((b) => b.outcome)).toEqual(["retreat", "flawless"]);
    expect(after.conceptsSinceBoss).toEqual([]);
    expect(s.bosses[1].outcome).toBeUndefined();
    expect(s.conceptsSinceBoss).toEqual(["a", "b", "c"]);
  });
});

import { describe, expect, it } from "vitest";
import { LEVEL_REWARDS, levelFor, rewardsBetween } from "./levels";
import { xpFor } from "./xp";

describe("xpFor", () => {
  it("scores answers", () => {
    expect(xpFor({ kind: "answer", verdict: "correct", afterMC: false })).toBe(10);
    expect(xpFor({ kind: "answer", verdict: "correct", afterMC: true })).toBe(5);
    expect(xpFor({ kind: "answer", verdict: "partial", afterMC: false })).toBe(5);
    expect(xpFor({ kind: "answer", verdict: "partial", afterMC: true })).toBe(5);
    expect(xpFor({ kind: "answer", verdict: "incorrect", afterMC: false })).toBe(0);
    expect(xpFor({ kind: "answer", verdict: "incorrect", afterMC: true })).toBe(0);
  });

  it("scores predictions", () => {
    expect(xpFor({ kind: "prediction", verdict: "correct" })).toBe(10);
    expect(xpFor({ kind: "prediction", verdict: "partial" })).toBe(5);
    expect(xpFor({ kind: "prediction", verdict: "incorrect" })).toBe(0);
  });

  it("scores boss hits, outcomes, and session completion", () => {
    expect(xpFor({ kind: "boss_hit", partial: false })).toBe(15);
    expect(xpFor({ kind: "boss_hit", partial: true })).toBe(8);
    expect(xpFor({ kind: "boss_outcome", outcome: "flawless" })).toBe(75);
    expect(xpFor({ kind: "boss_outcome", outcome: "victory" })).toBe(50);
    expect(xpFor({ kind: "boss_outcome", outcome: "retreat" })).toBe(20);
    expect(xpFor({ kind: "session_complete" })).toBe(30);
  });
});

describe("levelFor", () => {
  it("starts at level 1", () => {
    expect(levelFor(0)).toEqual({ level: 1, xp: 0, levelStartXp: 0, nextLevelXp: 100 });
  });

  it("crosses thresholds exactly at 100 / 250 / 450 / 700 / 1000 / 1350", () => {
    const cases: [number, number, number, number][] = [
      [99, 1, 0, 100],
      [100, 2, 100, 250],
      [249, 2, 100, 250],
      [250, 3, 250, 450],
      [449, 3, 250, 450],
      [450, 4, 450, 700],
      [699, 4, 450, 700],
      [700, 5, 700, 1000],
      [999, 5, 700, 1000],
      [1000, 6, 1000, 1350],
      [1350, 7, 1350, 1750],
    ];
    for (const [xp, level, levelStartXp, nextLevelXp] of cases) {
      expect(levelFor(xp)).toEqual({ level, xp, levelStartXp, nextLevelXp });
    }
  });

  it("keeps growing beyond level 10", () => {
    // L10 starts at 100+150+…+500 = 2700; L11 at 2700 + 550 = 3250
    expect(levelFor(2700).level).toBe(10);
    expect(levelFor(3250)).toEqual({ level: 11, xp: 3250, levelStartXp: 3250, nextLevelXp: 3850 });
  });

  it("treats negative XP as level 1", () => {
    expect(levelFor(-5)).toMatchObject({ level: 1, levelStartXp: 0, nextLevelXp: 100 });
  });
});

describe("rewards", () => {
  it("defines one reward per level from 2 to 10", () => {
    expect(LEVEL_REWARDS.map((r) => r.level)).toEqual([2, 3, 4, 5, 6, 7, 8, 9, 10]);
    expect(LEVEL_REWARDS.map((r) => r.id)).toEqual([
      "sunset",
      "marimba",
      "forest",
      "night",
      "retro",
      "sakura",
      "parchment",
      "nature",
      "matcha",
    ]);
    expect(LEVEL_REWARDS.filter((r) => r.kind === "sound_pack").map((r) => r.id)).toEqual([
      "marimba",
      "retro",
      "nature",
    ]);
  });

  it("returns rewards for levels in (from, to]", () => {
    expect(rewardsBetween(1, 1)).toEqual([]);
    expect(rewardsBetween(1, 2).map((r) => r.id)).toEqual(["sunset"]);
    expect(rewardsBetween(2, 5).map((r) => r.id)).toEqual(["marimba", "forest", "night"]);
    expect(rewardsBetween(9, 12).map((r) => r.id)).toEqual(["matcha"]);
    expect(rewardsBetween(10, 20)).toEqual([]);
  });

  it("returns copies, so callers can't mutate the table", () => {
    const [r] = rewardsBetween(1, 2);
    r.label = "changed";
    expect(LEVEL_REWARDS[0].label).toBe("Sunset theme");
  });

  it("composes with levelFor across a session", () => {
    const before = levelFor(90).level;
    const after = levelFor(90 + 200).level;
    expect(rewardsBetween(before, after).map((r) => r.id)).toEqual(["sunset", "marimba"]);
  });
});

import { describe, expect, it } from "vitest";
import { summarize } from "./summary";
import { ctx, DAY, outcomes, settings, stateWith, T0 } from "./test-helpers";

describe("summarize", () => {
  it("summarises a fresh session", () => {
    expect(summarize(ctx())).toEqual({
      guardrails: { enabled: false, mode: "balanced" },
      valueThreshold: 4,
      targetDifficulty: { firstExposure: 1, practice: 1 },
      masteredConcepts: [],
      conceptsSinceBoss: [],
      rollingAccuracy: null,
      recentOutcomes: [],
    });
  });

  it("reports the strict threshold and familiarity-based targets", () => {
    const s = summarize(ctx({ settings: settings({ enabled: true, mode: "strict" }), familiarity: "comfortable" }));
    expect(s.valueThreshold).toBe(5);
    expect(s.guardrails).toEqual({ enabled: true, mode: "strict" });
    expect(s.targetDifficulty).toEqual({ firstExposure: 2, practice: 2 });
  });

  it("lists mastered concepts, sorted, excluding unmastered and review-due ones", () => {
    const s = summarize(
      ctx({
        mastery: {
          zeta: { theta: 5, n: 2, lastSeen: T0 },
          alpha: { theta: 5, n: 4, lastSeen: T0 },
          weak: { theta: 3, n: 4, lastSeen: T0 },
          stale: { theta: 5, n: 4, lastSeen: T0 - DAY - 1 },
        },
      }),
    );
    expect(s.masteredConcepts).toEqual(["alpha", "zeta"]);
  });

  it("includes rolling accuracy, the last 3 outcomes, and concepts since boss", () => {
    const recent = outcomes([0, 1, 0.5, 1, 0.6, 1]);
    const s = summarize(ctx({ state: stateWith({ recentOutcomes: recent, conceptsSinceBoss: ["a", "b"] }) }));
    expect(s.rollingAccuracy).toBeCloseTo((1 + 0.5 + 1 + 0.6 + 1) / 5);
    expect(s.recentOutcomes).toEqual([
      { concept: "c", type: "decide", score: 1 },
      { concept: "c", type: "decide", score: 0.6 },
      { concept: "c", type: "decide", score: 1 },
    ]);
    expect(s.conceptsSinceBoss).toEqual(["a", "b"]);
  });

  it("applies the rolling adjustment to the advertised targets", () => {
    const hot = summarize(ctx({ familiarity: "comfortable", state: stateWith({ recentOutcomes: outcomes([1, 1, 1]) }) }));
    // comfortable practice raw 2.345 + 0.5 → 2.845 → 3
    expect(hot.targetDifficulty.practice).toBe(3);
  });
});

import { describe, expect, it } from "vitest";
import { initialEngineState } from "@/lib/contracts/engine";
import { engine, recordBossFinished, recordBossStarted, scoreFor } from "./index";
import { candidate, ctx, MIN, T0 } from "./test-helpers";

describe("engine (EngineApi)", () => {
  it("exposes every EngineApi function", () => {
    expect(Object.keys(engine).sort()).toEqual(
      [
        "bossDue",
        "bossOutcome",
        "gate",
        "isMastered",
        "levelFor",
        "recordOutcome",
        "recordShown",
        "recordWorkTurn",
        "reviewDue",
        "rewardsBetween",
        "summarize",
        "targetDifficulty",
        "updateMastery",
        "xpFor",
      ].sort(),
    );
  });

  it("runs a short session end to end", () => {
    const familiarity = "some" as const;
    let state = initialEngineState();
    let mastery = {} as Record<string, ReturnType<typeof engine.updateMastery>>;
    let now = T0;
    let xp = 0;

    for (const [i, concept] of ["split", "leakage", "scaling"].entries()) {
      state = engine.recordWorkTurn(state);
      const c = candidate({ concept, difficulty: 1 });
      expect(engine.gate(c, ctx({ state, mastery, familiarity, now }))).toEqual({ action: "show" });
      state = engine.recordShown(state, `m${i}`, now);
      // A second candidate while one is pending is held back.
      expect(engine.gate(c, ctx({ state, mastery, familiarity, now })).action).toBe("skip");

      const score = scoreFor("correct", false);
      mastery = { ...mastery, [concept]: engine.updateMastery(mastery[concept], score, c.difficulty, familiarity, now) };
      state = engine.recordOutcome(state, { momentId: `m${i}`, concept, type: c.type, score, at: now });
      xp += engine.xpFor({ kind: "answer", verdict: "correct", afterMC: false });
      now += 2 * MIN;
    }

    const endsAt = T0 + 10 * MIN;
    expect(engine.bossDue(state, now, endsAt)).toBe(true);
    state = recordBossStarted(state, { id: "b1", startedAt: now, concepts: [...state.conceptsSinceBoss] });
    expect(engine.bossDue(state, now + MIN, endsAt)).toBe(false);
    const outcome = engine.bossOutcome(2.5, 3);
    state = recordBossFinished(state, "b1", outcome);
    xp += engine.xpFor({ kind: "boss_outcome", outcome }) + engine.xpFor({ kind: "session_complete" });

    expect(state.conceptsSinceBoss).toEqual([]);
    expect(state.bosses[0].outcome).toBe("victory");
    expect(xp).toBe(110);
    expect(engine.rewardsBetween(engine.levelFor(0).level, engine.levelFor(xp).level).map((r) => r.id)).toEqual([
      "sunset",
    ]);
    expect(engine.summarize(ctx({ state, mastery, familiarity, now })).rollingAccuracy).toBe(1);
  });
});

