import { it } from "vitest";
import type { Familiarity, Outcome } from "@/lib/contracts/engine";
import { targetDifficulty } from "./difficulty";
import { pCorrect, updateMastery } from "./mastery";
import { outcome, seededRng, T0 } from "./test-helpers";

function sim(trueTheta: number, fam: Familiarity, seed: number, q: number, adjust: boolean) {
  const rng = seededRng(seed);
  let m: ReturnType<typeof updateMastery> | undefined;
  let recent: Outcome[] = [];
  const res: number[] = [];
  for (let i = 0; i < q; i++) {
    const kind = m ? "practice" : "first_exposure";
    const b = targetDifficulty(m, kind, fam, adjust ? recent : []);
    const s = rng() < pCorrect(trueTheta, b) ? 1 : 0;
    res.push(s);
    m = updateMastery(m, s, b, fam, T0 + i);
    recent = [...recent, outcome(s, i)].slice(-20);
  }
  return res;
}

it("probe", () => {
  for (const adjust of [true, false]) {
    for (const t of [2.5, 3, 3.5, 4, 4.5, 5, 5.5]) {
      let first30 = 0, late = 0;
      const N = 400;
      for (let s = 1; s <= N; s++) {
        const r = sim(t, "some", s, 90, adjust);
        first30 += r.slice(0, 30).reduce((a, b) => a + b, 0) / 30;
        late += r.slice(30).reduce((a, b) => a + b, 0) / 60;
      }
      console.log(`adjust=${adjust} θ*=${t} first30=${(first30 / N).toFixed(3)} steady=${(late / N).toFixed(3)}`);
    }
  }
});

